import {owned} from './catalog-state.svelte.js';import {tick} from 'svelte';import {currentModal} from './modal-state.js';let {current,index,total,previous,next,stop,waiting=false,missing=false,anchor,panel,suppressEntry=false}:{current:{title:string;instruction:string};index:number;total:number;previous:()=>void;next:()=>void;stop:()=>void;waiting?:boolean;missing?:boolean;suppressEntry?:boolean;panel?:HTMLElement|null;anchor?:{left:number;top:number;width:number;height:number;targetId?:string}}=$props();let heading:HTMLHeadingElement;let popover:HTMLElement;let left=$state(8),top=$state(8),maxHeight=$state(500),maxWidth=$state(576);$effect(()=>{const target=anchor;let active=true;if(target)void tick().then(()=>{if(!active||!popover?.isConnected)return;maxWidth=innerWidth-16;const associated=panel;const targetNode=target.targetId?document.getElementById(target.targetId):null;if(associated?.getClientRects().length&&!associated.contains(targetNode)){const panelBox=associated.getBoundingClientRect();if(panelBox.left>target.left)maxWidth=Math.min(maxWidth,Math.max(80,panelBox.left-target.left-8));}const width=Math.min(popover.getBoundingClientRect().width,maxWidth);left=Math.max(8,Math.min(target.left,innerWidth-width-8));const below=innerHeight-target.top-target.height-16,above=target.top-16;top=below>=160||below>=above?Math.max(8,target.top+target.height+8):8;maxHeight=Math.max(80,top===8&&above>below?above:innerHeight-top-8);});return()=>{active=false;};});let previousIndex=-1;$effect(()=>{const actual=index;if(actual!==previousIndex){previousIndex=actual;let active=true;const focusBefore=heading?.ownerDocument.activeElement;void tick().then(()=>{const modal=currentModal();const focusNow=heading?.ownerDocument.activeElement;if(active&&!suppressEntry&&heading?.isConnected&&(focusNow===focusBefore||focusNow===heading.ownerDocument.body)&&(!modal||modal.contains(heading))){heading.focus({preventScroll:true});}});return()=>{active=false;};}});
